def pancake_sort(lst):
    for curr_size in range(len(lst), 1, -1):
        max_idx = 0
        for i in range(1, curr_size):
            if lst[i] > lst[max_idx]:
                max_idx = i
        lst = flip(lst, max_idx)
        lst = flip(lst, curr_size-1)
    return lst

def flip(lst, i):
    start = 0
    while start < i:
        lst[start], lst[i] = lst[i], lst[start]
        start += 1
        i -= 1
    return lst

def flip(arr, i):
    start = 0
    while start < i:
        arr[start], arr[i] = arr[i], arr[start]
        start += 1
        i -= 1
    return arr

